import { Badge } from "@/components/ui/badge"
import { Breadcrumb, BreadcrumbItem, BreadcrumbLink, BreadcrumbList, BreadcrumbPage } from "@/components/ui/breadcrumb"
import { LinkButton } from "@/components/ui/button"

/**
 * Page header: breadcrumbs, title, description, meta badges and actions.
 * config.standard is a page title; config.record adds record meta (status
 * badges) beside the title; contact.header stacks it centered for contact pages.
 */
export default function PageHeader({
  config = "standard",
  title = "Projects",
  description = "Everything your team is building, in one place.",
  breadcrumbs = [{ label: "Home", href: "/" }, { label: "Projects" }],
  meta = [],
  actions = [{ label: "New project", href: "#" }],
}: {
  config?: "standard" | "record" | "contact"
  title?: string
  description?: string
  breadcrumbs?: { label: string; href?: string }[]
  meta?: string[]
  actions?: { label: string; href: string }[]
}) {
  const centered = config === "contact"
  return (
    <section data-slot="page-header" data-config={config} className="border-b border-border py-8">
      <div className={centered ? "mx-auto max-w-2xl px-6 text-center" : "mx-auto max-w-5xl px-6"}>
        {breadcrumbs.length > 1 && !centered && (
          <Breadcrumb className="mb-4">
            <BreadcrumbList>
              {breadcrumbs.map((b, i) => (
                <BreadcrumbItem key={`${b.label}-${i}`}>
                  {b.href && i < breadcrumbs.length - 1 ? <BreadcrumbLink href={b.href}>{b.label}</BreadcrumbLink> : <BreadcrumbPage>{b.label}</BreadcrumbPage>}
                </BreadcrumbItem>
              ))}
            </BreadcrumbList>
          </Breadcrumb>
        )}
        <div className={centered ? "space-y-3" : "flex flex-col gap-4 md:flex-row md:items-end md:justify-between"}>
          <div className="min-w-0 space-y-2">
            <div className={centered ? "flex justify-center" : "flex flex-wrap items-center gap-2"}>
              <h1 className="font-heading text-3xl font-semibold tracking-tight text-balance">{title}</h1>
              {config === "record" && meta.map((m) => <Badge key={m} variant="secondary">{m}</Badge>)}
            </div>
            {description && <p className="max-w-2xl text-muted-foreground">{description}</p>}
          </div>
          {actions.length > 0 && (
            <div className={centered ? "flex justify-center gap-2" : "flex shrink-0 gap-2"}>
              {actions.map((a, i) => (
                <LinkButton key={a.label} href={a.href} variant={i === 0 ? "default" : "outline"}>
                  {a.label}
                </LinkButton>
              ))}
            </div>
          )}
        </div>
      </div>
    </section>
  )
}
